/**
 * Writes `types.rs`: the contract's declarations, `RpcError`, and the
 * conversions both Rust sides share.
 */

import type { ObjectTypeDeclaration, RpcSchema, StringEnumTypeDeclaration } from "../schema";
import { RPC_ERROR_EVENT } from "../types";
import { rustTypeName, rustValueIdentifier } from "./names";
import { enumVariantName, isBoxedField, renderRustType, unwrapOptionality, type DeclarationScope } from "./project";

export function header(what: string): string[] {
  return [
    "// Code generated by socketrpc-gen. DO NOT EDIT.",
    "//",
    `// ${what}`,
    "",
  ];
}

const RUNTIME = String.raw`/// Wire event carrying an [${"`"}RpcError${"`"}] raised by a fire-and-forget handler back to the peer.
pub const RPC_ERROR_EVENT: &str = "${RPC_ERROR_EVENT}";

/// An error code: one of the standard codes, or any string a handler chose.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub enum RpcErrorCode {
    Timeout,
    Disposed,
    Disconnected,
    Aborted,
    InternalError,
    InvalidArgument,
    Other(String),
}

impl RpcErrorCode {
    pub fn as_str(&self) -> &str {
        match self {
            Self::Timeout => "TIMEOUT",
            Self::Disposed => "DISPOSED",
            Self::Disconnected => "DISCONNECTED",
            Self::Aborted => "ABORTED",
            Self::InternalError => "INTERNAL_ERROR",
            Self::InvalidArgument => "INVALID_ARGUMENT",
            Self::Other(code) => code,
        }
    }
}

impl From<&str> for RpcErrorCode {
    fn from(code: &str) -> Self {
        match code {
            "TIMEOUT" => Self::Timeout,
            "DISPOSED" => Self::Disposed,
            "DISCONNECTED" => Self::Disconnected,
            "ABORTED" => Self::Aborted,
            "INTERNAL_ERROR" => Self::InternalError,
            "INVALID_ARGUMENT" => Self::InvalidArgument,
            other => Self::Other(other.to_string()),
        }
    }
}

impl From<String> for RpcErrorCode {
    fn from(code: String) -> Self {
        Self::from(code.as_str())
    }
}

impl ::std::fmt::Display for RpcErrorCode {
    fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
        f.write_str(self.as_str())
    }
}

impl ::serde::Serialize for RpcErrorCode {
    fn serialize<S: ::serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        serializer.serialize_str(self.as_str())
    }
}

impl<'de> ::serde::Deserialize<'de> for RpcErrorCode {
    fn deserialize<D: ::serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
        <String as ::serde::Deserialize>::deserialize(deserializer).map(Self::from)
    }
}

/// An error that occurred during an RPC call.
///
/// On the wire it is the branded object every SocketRPC peer understands:
/// ${"`"}{ "__rpcError": true, "code", "message", "method"?, "data"? }${"`"}. A handler
/// signals failure by returning one; a caller receives one for a failed call.
#[derive(Debug, Clone, PartialEq, ::serde::Serialize, ::serde::Deserialize)]
#[serde(into = "RpcErrorWire", try_from = "RpcErrorWire")]
pub struct RpcError {
    pub code: RpcErrorCode,
    pub message: String,
    /// The RPC method the error originated in.
    pub method: Option<String>,
    /// Optional error-specific payload.
    pub data: Option<::serde_json::Value>,
}

impl RpcError {
    pub fn new(code: impl Into<RpcErrorCode>, message: impl Into<String>) -> Self {
        Self { code: code.into(), message: message.into(), method: None, data: None }
    }

    /// An ${"`"}INTERNAL_ERROR${"`"} carrying ${"`"}message${"`"}: the conversion for any other failure.
    pub fn internal(message: impl ::std::fmt::Display) -> Self {
        Self::new(RpcErrorCode::InternalError, message.to_string())
    }

    pub fn invalid_argument(message: impl Into<String>) -> Self {
        Self::new(RpcErrorCode::InvalidArgument, message)
    }

    pub fn with_data(mut self, data: ::serde_json::Value) -> Self {
        self.data = Some(data);
        self
    }

    pub fn with_method(mut self, method: impl Into<String>) -> Self {
        self.method = Some(method.into());
        self
    }

    pub(super) fn in_method(mut self, method: &str) -> Self {
        if self.method.is_none() {
            self.method = Some(method.to_string());
        }
        self
    }
}

impl ::std::fmt::Display for RpcError {
    fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
        match &self.method {
            Some(method) => write!(f, "{} ({}): {}", self.code, method, self.message),
            None => write!(f, "{}: {}", self.code, self.message),
        }
    }
}

impl ::std::error::Error for RpcError {}

#[derive(::serde::Serialize, ::serde::Deserialize)]
struct RpcErrorWire {
    #[serde(rename = "__rpcError")]
    brand: bool,
    code: RpcErrorCode,
    message: String,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    method: Option<String>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    data: Option<::serde_json::Value>,
}

impl From<RpcError> for RpcErrorWire {
    fn from(error: RpcError) -> Self {
        Self { brand: true, code: error.code, message: error.message, method: error.method, data: error.data }
    }
}

impl TryFrom<RpcErrorWire> for RpcError {
    type Error = &'static str;

    fn try_from(wire: RpcErrorWire) -> Result<Self, Self::Error> {
        if !wire.brand {
            return Err("not an RpcError: __rpcError is not true");
        }
        Ok(Self { code: wire.code, message: wire.message, method: wire.method, data: wire.data })
    }
}

/// Removes the observer it was returned for. Dropping it keeps the observer.
#[must_use = "dropping an Unsubscribe keeps the observer registered; call .unsubscribe() to remove it"]
pub struct Unsubscribe(Box<dyn FnOnce() + Send>);

impl Unsubscribe {
    #[allow(dead_code)]
    pub(super) fn new(remove: impl FnOnce() + Send + 'static) -> Self {
        Self(Box::new(remove))
    }

    pub fn unsubscribe(self) {
        (self.0)()
    }
}

impl ::std::fmt::Debug for Unsubscribe {
    fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {
        f.write_str("Unsubscribe")
    }
}

/// Encodes call arguments, refusing a value serde_json cannot represent.
#[allow(dead_code)]
pub(super) fn rpc_encode_args(
    method: &str,
    args: Vec<::serde_json::Result<::serde_json::Value>>,
) -> Result<Vec<::serde_json::Value>, RpcError> {
    args.into_iter()
        .collect::<Result<Vec<_>, _>>()
        .map_err(|err| RpcError::invalid_argument(format!("cannot encode argument: {err}")).in_method(method))
}

/// Encodes a handler's result for the acknowledgement.
#[allow(dead_code)]
pub(super) fn rpc_encode_result<T: ::serde::Serialize>(value: T) -> Result<::serde_json::Value, RpcError> {
    ::serde_json::to_value(value).map_err(|err| RpcError::internal(format!("cannot encode result: {err}")))
}

/// Decodes positional argument ${"`"}index${"`"} of an inbound call.
#[allow(dead_code)]
pub(super) fn rpc_decode_arg<T: ::serde::de::DeserializeOwned>(
    args: &mut ::std::vec::IntoIter<::serde_json::Value>,
    name: &str,
) -> Result<T, RpcError> {
    let value = args.next().unwrap_or(::serde_json::Value::Null);
    ::serde_json::from_value(value).map_err(|err| RpcError::invalid_argument(format!("invalid argument {name}: {err}")))
}

/// Reads an acknowledgement: the peer's branded error, or the result.
#[allow(dead_code)]
pub(super) fn rpc_decode_result<T: ::serde::de::DeserializeOwned>(
    method: &str,
    value: ::serde_json::Value,
) -> Result<T, RpcError> {
    if value.get("__rpcError") == Some(&::serde_json::Value::Bool(true)) {
        return Err(::serde_json::from_value::<RpcError>(value)
            .unwrap_or_else(|err| RpcError::invalid_argument(format!("malformed RpcError: {err}")))
            .in_method(method));
    }
    ::serde_json::from_value(value).map_err(|err| {
        RpcError::invalid_argument(format!("invalid acknowledgement payload: {err}")).in_method(method)
    })
}

/// Reads a panic's message, for the INTERNAL_ERROR a panicking handler answers with.
#[allow(dead_code)]
pub(super) fn rpc_panic_message(payload: Box<dyn ::std::any::Any + Send>) -> String {
    match payload.downcast::<String>() {
        Ok(message) => *message,
        Err(payload) => match payload.downcast::<&'static str>() {
            Ok(message) => (*message).to_string(),
            Err(_) => "handler panicked".to_string(),
        },
    }
}

/// ${"`"}Option<Option<T>>${"`"} for a field that may be omitted or null: the outer
/// ${"`"}None${"`"} is an omitted key, ${"`"}Some(None)${"`"} an explicit null.
#[allow(dead_code)]
mod rpc_double_option {
    pub fn serialize<T: ::serde::Serialize, S: ::serde::Serializer>(
        value: &Option<Option<T>>,
        serializer: S,
    ) -> Result<S::Ok, S::Error> {
        match value {
            Some(inner) => ::serde::Serialize::serialize(inner, serializer),
            None => serializer.serialize_none(),
        }
    }

    pub fn deserialize<'de, T: ::serde::Deserialize<'de>, D: ::serde::Deserializer<'de>>(
        deserializer: D,
    ) -> Result<Option<Option<T>>, D::Error> {
        <Option<T> as ::serde::Deserialize>::deserialize(deserializer).map(Some)
    }
}
`;

function docLine(text: string): string {
  return `/// ${text}`;
}

function emitEnum(declaration: StringEnumTypeDeclaration): string[] {
  const name = rustTypeName(declaration.name);
  const variants = declaration.values.map((value) => ({ value, variant: enumVariantName(value) }));
  return [
    docLine(`One of ${declaration.values.map((value) => JSON.stringify(value)).join(", ")}.`),
    "#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, ::serde::Serialize, ::serde::Deserialize)]",
    `pub enum ${name} {`,
    ...variants.flatMap(({ value, variant }) => [`    #[serde(rename = ${JSON.stringify(value)})]`, `    ${variant},`]),
    "}",
    "",
    `impl ${name} {`,
    `    pub const ALL: [Self; ${variants.length}] = [${variants.map(({ variant }) => `Self::${variant}`).join(", ")}];`,
    "",
    "    /// The literal this variant travels as.",
    "    pub fn as_str(self) -> &'static str {",
    "        match self {",
    ...variants.map(({ value, variant }) => `            Self::${variant} => ${JSON.stringify(value)},`),
    "        }",
    "    }",
    "}",
    "",
    `impl ::std::fmt::Display for ${name} {`,
    "    fn fmt(&self, f: &mut ::std::fmt::Formatter<'_>) -> ::std::fmt::Result {",
    "        f.write_str(self.as_str())",
    "    }",
    "}",
  ];
}

function emitObject(declaration: ObjectTypeDeclaration, declarations: DeclarationScope): string[] {
  const name = rustTypeName(declaration.name);
  const fields = declaration.fields.flatMap((field) => {
    const rustName = rustValueIdentifier(field.name);
    const { core, optional, nullable } = unwrapOptionality(field.type);
    const attributes: string[] = [];
    if (rustName !== field.name) attributes.push(`rename = ${JSON.stringify(field.name)}`);
    if (core.kind === "json") {
      // A missing key reads as null, as TypeScript's JSON.stringify drops undefined.
      attributes.push(optional ? `default, skip_serializing_if = "Option::is_none"` : "default");
    } else if (optional && nullable) {
      attributes.push(`default, skip_serializing_if = "Option::is_none", with = "rpc_double_option"`);
    } else if (optional) {
      attributes.push(`default, skip_serializing_if = "Option::is_none"`);
    }
    return [
      ...(attributes.length > 0 ? [`    #[serde(${attributes.join(", ")})]`] : []),
      `    pub ${rustName}: ${renderRustType(field.type, isBoxedField(declaration.name, field, declarations))},`,
    ];
  });
  return [
    "#[derive(Debug, Clone, PartialEq, ::serde::Serialize, ::serde::Deserialize)]",
    ...(fields.length === 0 ? [`pub struct ${name} {}`] : [`pub struct ${name} {`, ...fields, "}"]),
  ];
}

export function emitTypesFile(schema: RpcSchema, declarations: DeclarationScope): string {
  const blocks = schema.declarations.map((declaration) => {
    switch (declaration.kind) {
      case "enum":
        return emitEnum(declaration);
      case "object":
        return emitObject(declaration, declarations);
      case "alias":
        return [`pub type ${rustTypeName(declaration.name)} = ${renderRustType(declaration.target)};`];
    }
  });
  return [
    ...header("Contract types and the RpcError both Rust sides share."),
    RUNTIME,
    ...blocks.flatMap((block) => [...block, ""]),
  ]
    .join("\n")
    .replace(/\n+$/, "\n");
}
